import{_ as e,o as i,c as s,a2 as n}from"./chunks/framework.CqGPl1zp.js";const t="/newx-doc/assets/%E4%BD%BF%E7%94%A8%E7%A4%BA%E4%BE%8B.BSQJJ5bp.png",b=JSON.parse('{"title":"联网搜索","description":"","frontmatter":{},"headers":[],"relativePath":"ai/web-search.md","filePath":"ai/web-search.md","lastUpdated":null}'),r={name:"ai/web-search.md"};function l(h,a,p,o,c,d){return i(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="联网搜索" tabindex="-1">联网搜索 <a class="header-anchor" href="#联网搜索" aria-label="Permalink to &quot;联网搜索&quot;">​</a></h1><p>除了使用 <a href="./knowledge">《AI 知识库》</a> 来增强 AI 推理结果外，也可以使用联网搜索的方式，来增强 AI 的知识面，本质上它也是一种“知识库”。</p><h2 id="_1-aiwebsearchclient" tabindex="-1">1. AiWebSearchClient <a class="header-anchor" href="#_1-aiwebsearchclient" aria-label="Permalink to &quot;1. AiWebSearchClient&quot;">​</a></h2><p>AiWebSearchClient 是一个接口，定义了联网搜索的能力，定义了 <code>#search(...)</code> 方法，用于执行网页搜索。</p><p>友情提示：除了网页搜索，后续也会增加图片、视频等搜索能力，进一步增强 AI 的知识面。</p><p>它目前的实现类有：</p><ul><li>AiBoChaWebSearchClient：对接 <a href="https://open.bochaai.com/overview" target="_blank" rel="noreferrer">博查</a> 的搜索 API 。</li></ul><p>后续，你也可以按需实现自己的搜索客户端，例如说：</p><ul><li><a href="https://github.com/ptonlix/LangChain-SearXNG" target="_blank" rel="noreferrer">《LangChain-SearXNG：AI Q&amp;A Search Engine ➡️ 基于LangChain和SearXNG打造的开源AI搜索引擎》</a></li><li><a href="https://help.aliyun.com/zh/open-search/search-platform/developer-reference/web-search" target="_blank" rel="noreferrer">《阿里云 —— 联网搜索》</a></li></ul><h2 id="_2-如何配置" tabindex="-1">2. 如何配置？ <a class="header-anchor" href="#_2-如何配置" aria-label="Permalink to &quot;2. 如何配置？&quot;">​</a></h2><p>① 在 <code>application.yaml</code> 中，配置 <code>yudao.ai.web-search</code> 配置项，开启和配置对应的 API KEY ，如下所示：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    web-search</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-40500e52840f4d24b956d0b1d80d9abe</span></span></code></pre></div><p>② 【二次开发情况下】修改 AiAutoConfiguration 类的 <code>#webSearchClient()</code> 方法，返回你自己实现的 AiWebSearchClient 实例。</p><h2 id="_3-使用示例" tabindex="-1">3. 使用示例？ <a class="header-anchor" href="#_3-使用示例" aria-label="Permalink to &quot;3. 使用示例？&quot;">​</a></h2><p><img src="`+t+'" alt="使用示例"></p>',15)])])}const E=e(r,[["render",l]]);export{b as __pageData,E as default};
